  } else {
    var head2 = gasTop - pistonH - 6, tail2 = head2 - L;
    vArrow(g, ax, tail2, head2, C.work, 2.2, 5, 10);
    labelY = tail2 - 9;
  }
  richText(g, ax, labelY, [{ t: 'W', italic: true }, { t: P.w, sub: true }], { size: 16, family: MATHFAM, halo: true });

  // heat arrow (only for reservoir panels, hidden by the boundary filter)
  if (P.heat && boundaryOK(i)) {
    if (P.heat === 'in') vArrow(g, cx, 294, 258, C.heat, 9, 10, 15);
    else vArrow(g, cx, 258, 294, C.heat, 9, 10, 15);
    richText(g, cx, 314, [{ t: 'Q', italic: true }, { t: (P.heat === 'in' ? 'h' : 'c'), sub: true }],
      { size: 16, family: MATHFAM, halo: true });
  }

  // block label + temperature line
  richText(g, cx, 336, [{ t: P.block }], { size: 14.5, halo: true });
  if (P.temp) {
    richText(g, cx, 370, [{ t: '(Temperature ' }, { t: 'T', italic: true }, { t: P.temp, sub: true }, { t: ')' }],
      { size: 13, family: MATHFAM });
  }

  // captions
  richText(g, cx, 406, [{ t: P.cap1, bold: true }], { size: 14 });
  richText(g, cx, 426, [{ t: P.cap2 }], { size: 13 });
  richText(g, cx, 446, [{ t: P.cap3 }], { size: 13 });

  if (!active) g.opacity(0.5);
  if (active && anySelection()) {
    g.rect(CP.BW + 12, CP.BH + 12).move(bx - 6, CP.BY - 6).radius(5)
      .fill('none').stroke({ color: C.ring, width: 3 });
  }

  // hit area for hover / click
  var hit = g.rect(CP.BW + 12, 450).move(bx - 6, 4).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(P.tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      state.cycleStep = ['step1_MN', 'step2_NO', 'step3_OP', 'step4_PM'][i];
      syncControls(); render();
      showPopup(P.ptitle, P.pbody);
    });
}

/* ---------- p-V diagram ---------- */
var GAM = 1.9, TH = 1.0, TC = 0.45, VM = 1.0, VN = 1.7;
var RAT = Math.pow(TH / TC, 1 / (GAM - 1));
var VO = VN * RAT, VP = VM * RAT;
var pM = TH / VM, pN = TH / VN, pO = TC / VO, pP = TC / VP;

var fIsoH = compileExpr(TH + '/V', ['V']);
var fIsoC = compileExpr(TC + '/V', ['V']);
var fAdNO = compileExpr(pN.toFixed(6) + '*(' + VN.toFixed(6) + '/V)^' + GAM, ['V']);
var fAdPM = compileExpr(pP.toFixed(6) + '*(' + VP.toFixed(6) + '/V)^' + GAM, ['V']);

function pvx(V) { return 85 + (V - 0.7) * (505 / 4.2); }
function pvy(p) { return 380 - (p - 0.05) * (320 / 1.10); }

function sampleCurve(fn, a, b, n) {
  var pts = [];
  for (var k = 0; k < n; k++) {
    var V = a + (b - a) * (k / (n - 1));
    pts.push([pvx(V), pvy(fn(V))]);
  }
  return pts;
}
function ptsAttr(p) { return p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' '); }

function midArrow(g, pts, color, size) {
  var k = Math.floor(pts.length / 2);
  var a = pts[k - 1], b = pts[k + 1];
  var dx = b[0] - a[0], dy = b[1] - a[1], L = Math.sqrt(dx * dx + dy * dy) || 1;
  dx /= L; dy /= L;
  var nx = -dy, ny = dx, c = pts[k];
  var tip = [c[0] + dx * size, c[1] + dy * size];
  var bx = c[0] - dx * size * 0.5, by = c[1] - dy * size * 0.5;
  g.polygon([[bx + nx * size * 0.62, by + ny * size * 0.62], [bx - nx * size * 0.62, by - ny * size * 0.62], tip]).fill(color);
}

function drawPV(root) {
  var g = root.group();

  var SEGS = [
    { fn: fIsoH, a: VM, b: VN, color: C.hotCurve, tip: 'M\u2192N: isothermal expansion at T_h (heat Q_h in)', idx: 0 },
    { fn: fAdNO, a: VN, b: VO, color: C.adiabat, tip: 'N\u2192O: adiabatic expansion, Q = 0 (T_h \u2192 T_c)', idx: 1 },
    { fn: fIsoC, a: VO, b: VP, color: C.coldCurve, tip: 'O\u2192P: isothermal compression at T_c (heat Q_c out)', idx: 2 },
    { fn: fAdPM, a: VP, b: VM, color: C.adiabat, tip: 'P\u2192M: adiabatic compression, Q = 0 (T_c \u2192 T_h)', idx: 3 }
  ];
  var sampled = SEGS.map(function (s) { return sampleCurve(s.fn, s.a, s.b, 60); });

  // shaded loop interior
  var loop = [];
  sampled.forEach(function (p) { loop = loop.concat(p); });
  g.polygon(ptsAttr(loop)).fill('#bcd9f2').opacity(0.42).stroke('none');

  // dashed isotherm guides
  g.polyline(ptsAttr(sampleCurve(fIsoH, 0.85, 4.9, 80))).fill('none')
    .stroke({ color: C.hotCurve, width: 1.2, dasharray: '5,4' }).opacity(0.75);
  g.polyline(ptsAttr(sampleCurve(fIsoC, 0.85, 4.9, 80))).fill('none')
    .stroke({ color: C.coldCurve, width: 1.2, dasharray: '5,4' }).opacity(0.75);

  // axes
  g.line(68, 390, 600, 390).stroke({ color: '#333', width: 1.6 });
  g.polygon([[600, 385], [600, 395], [610, 390]]).fill('#333');
  g.line(68, 390, 68, 46).stroke({ color: '#333', width: 1.6 });
  g.polygon([[63, 46], [73, 46], [68, 36]]).fill('#333');
  richText(g, 610, 408, [{ t: 'V', italic: true }], { size: 16, family: MATHFAM, anchor: 'middle' });
  richText(g, 52, 44, [{ t: 'p', italic: true }], { size: 16, family: MATHFAM, anchor: 'middle' });

  // curve legs
  SEGS.forEach(function (s, k) {
    var on = legActive(s.idx);
    var pts = sampled[k];
    var w = on ? (anySelection() ? 4.2 : 3.2) : 2;
    var poly = g.polyline(ptsAttr(pts)).fill('none')
      .stroke({ color: s.color, width: w, linecap: 'round', linejoin: 'round' })
      .opacity(on ? 1 : 0.28);
    midArrow(g, pts, s.color, on ? 9 : 7).opacity(on ? 1 : 0.28);
    var hit = g.polyline(ptsAttr(pts)).fill('none').stroke({ color: '#fff', width: 14, linecap: 'round' }).opacity(0);
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip(s.tip, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        state.cycleStep = ['step1_MN', 'step2_NO', 'step3_OP', 'step4_PM'][s.idx];
        syncControls(); render();
        showPopup(PANELS[s.idx].ptitle, PANELS[s.idx].pbody);
      });
  });

  // corner points + labels
  var corners = [
    { V: VM, p: pM, t: 'M', x: -10, y: -6, an: 'end' },
    { V: VN, p: pN, t: 'N', x: 9, y: -6, an: 'start' },
    { V: VO, p: pO, t: 'O', x: 8, y: -11, an: 'start' },
    { V: VP, p: pP, t: 'P', x: -8, y: 15, an: 'end' }
  ];
  corners.forEach(function (c) {
    var X = pvx(c.V), Y = pvy(c.p);
    g.circle(7).center(X, Y).fill('#2b2b2b');
    richText(g, X + c.x, Y + c.y, [{ t: c.t, italic: true }], { size: 15, family: MATHFAM, anchor: c.an, halo: true });
  });

  // isotherm guide labels
  richText(g, 598, pvy(TH / 4.9), [{ t: 'T', italic: true }, { t: 'h', sub: true }],
    { size: 14, family: MATHFAM, anchor: 'start', fill: C.hotCurve, halo: true });
  richText(g, 598, pvy(TC / 4.9), [{ t: 'T', italic: true }, { t: 'c', sub: true }],
    { size: 14, family: MATHFAM, anchor: 'start', fill: C.coldCurve, halo: true });

  // net work callout with leader
  g.line(418, 203, 272, 303).stroke({ color: '#7a7a7a', width: 1, dasharray: '3,3' });
  g.circle(5).center(272, 303).fill('#7a7a7a');
  richText(g, 442, 196, [{ t: 'net work ' }, { t: 'W', italic: true }], { size: 13.5, halo: true });

  // legend
  var lg = g.group(), ly = 445;
  function swatch(x, fill, stroke) { lg.rect(16, 11).move(x, ly - 9).fill(fill).stroke({ color: stroke, width: 1 }); }
  lg.line(20, ly - 4, 36, ly - 4).stroke({ color: C.work, width: 2.4 });
  lg.polygon([[36, ly - 8], [36, ly], [43, ly - 4]]).fill(C.work);
  richText(lg, 48, ly, [{ t: 'work' }], { size: 11.5, anchor: 'start' });
  lg.line(100, ly - 4, 116, ly - 4).stroke({ color: C.heat, width: 7 });
  lg.polygon([[116, ly - 9], [116, ly + 1], [125, ly - 4]]).fill(C.heat);
  richText(lg, 130, ly, [{ t: 'heat' }], { size: 11.5, anchor: 'start' });
  swatch(180, C.hotFill, C.hotStroke); richText(lg, 200, ly, [{ t: 'hot reservoir' }], { size: 11.5, anchor: 'start' });
  swatch(290, C.coldFill, C.coldStroke); richText(lg, 310, ly, [{ t: 'cold reservoir' }], { size: 11.5, anchor: 'start' });
  swatch(404, C.insFill, C.insStroke); richText(lg, 424, ly, [{ t: 'insulation' }], { size: 11.5, anchor: 'start' });
  lg.line(500, ly - 4, 522, ly - 4).stroke({ color: '#888', width: 1.2, dasharray: '5,4' });
  richText(lg, 528, ly, [{ t: 'isotherm guides' }], { size: 11.5, anchor: 'start' });

  return g;
}

/* ---------- render ---------- */
function render() {
  cDraw.clear();
  if (state.rep === 'piston panels') {
    cDraw.viewbox(0, 0, 780, 470);
    drawPanels(cDraw.group());
  } else if (state.rep === 'p-V path') {
    cDraw.viewbox(0, 0, 660, 490);
    var gp = cDraw.group(); drawPV(gp); gp.attr('transform', 'translate(10,10)');
  } else {
    cDraw.viewbox(0, 0, 1280, 440);
    var a = cDraw.group(); drawPanels(a); a.attr('transform', 'translate(6,10) scale(0.86)');
    var b = cDraw.group(); drawPV(b); b.attr('transform', 'translate(694,6) scale(0.86)');
  }
}

/* ---------- controls ---------- */
function syncControls() {
  document.getElementById('cycleStepInput').value = state.cycleStep;
  document.getElementById('boundaryContactInput').value = state.boundary;
  document.getElementById('representationInput').value = state.rep;
}
function update_cycleStep(v) { state.cycleStep = v; render(); }
function update_boundaryContact(v) { state.boundary = v; render(); }
function update_representation(v) { state.rep = v; render(); }

function showKeyInsight() {
  showPopup('Why only T_h and T_c matter',
    'Heat enters the working gas only during the hot isothermal leg and leaves only during the cold isothermal leg; the two insulated legs carry the gas between T_h and T_c with Q = 0. Because the closed loop returns to its starting state, the enclosed area is the net work W = Q_h \u2212 Q_c, and for reversible isotherms Q_c/Q_h = T_c/T_h, so the efficiency is 1 \u2212 T_c/T_h.');
}

/* ---------- demo player ---------- */
var demoSteps = [
  { title: 'Step 1 \u2014 Isothermal expansion (M\u2192N)', narration: 'The cylinder sits on the hot reservoir at T_h. Heat Q_h flows in (gray arrow up) exactly as fast as the gas does work W1 lifting the piston, so the temperature never changes and the gas expands.', state: { cycleStep: 'step1_MN', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 2 \u2014 Adiabatic expansion (N\u2192O)', narration: 'The cylinder is now wrapped in insulation, so no heat arrow appears. The gas keeps expanding and does work W2, but that energy can only come from its own internal energy, so it cools from T_h to T_c.', state: { cycleStep: 'step2_NO', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 3 \u2014 Isothermal compression (O\u2192P)', narration: 'Placed on the cold reservoir at T_c, the gas is compressed: work W3 is done on it downward while heat Q_c is dumped out to the cold reservoir, holding the temperature fixed.', state: { cycleStep: 'step3_OP', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 4 \u2014 Adiabatic compression (P\u2192M)', narration: 'Insulated again, the gas is compressed to its smallest volume by work W4 with no heat exchange, which raises its temperature back to T_h and returns it to state M.', state: { cycleStep: 'step4_PM', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Where heat crosses the boundary', narration: 'Filter to the thermal-contact steps only: heat enters in Step 1 and leaves in Step 3. Every other energy transfer in the cycle is work, not heat.', state: { cycleStep: 'fullCycle', boundary: 'thermal contact (isothermal steps)', rep: 'piston panels' } },
  { title: 'Insulated legs change temperature, not heat', narration: 'Now filter to the insulated steps. With Q = 0, the work done goes entirely into or out of internal energy, which is what carries the gas between T_h and T_c.', state: { cycleStep: 'fullCycle', boundary: 'insulated (adiabatic steps)', rep: 'piston panels' } },
  { title: 'The same cycle as a p\u2013V loop', narration: 'Switch to the p\u2013V view: the four panels become the four legs of a closed clockwise loop M\u2192N\u2192O\u2192P\u2192M. The shallow legs are isotherms, the steep legs adiabats, and the enclosed area is the net work output.', state: { cycleStep: 'fullCycle', boundary: 'all four steps', rep: 'p-V path' } },
  { title: 'Linking picture to path', narration: 'Side by side, stepping through the cycle highlights one cylinder and its matching curve segment together, so piston motion, heat flow, and position on the loop are read as a single process.', state: { cycleStep: 'step1_MN', boundary: 'all four steps', rep: 'side by side' } }
];
var demoIndex = 0;

function applyDemoStep(i) {
  demoIndex = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  var s = demoSteps[demoIndex];
  state.cycleStep = s.state.cycleStep;
  state.boundary = s.state.boundary;
  state.rep = s.state.rep;
  syncControls();
  render();
  document.getElementById('demoTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
}
function prevStep() { applyDemoStep(demoIndex - 1); }
function nextStep() { applyDemoStep(demoIndex + 1); }

applyDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

