    <option value="fullCycle">Full cycle (all four)</option>
    <option value="step1_MN">Step 1 — isothermal expansion (M→N)</option>
    <option value="step2_NO">Step 2 — adiabatic expansion (N→O)</option>
    <option value="step3_OP">Step 3 — isothermal compression (O→P)</option>
    <option value="step4_PM">Step 4 — adiabatic compression (P→M)</option>
  </select>
</label>
<label>Show boundary condition:
  <select id="boundaryContactInput" onchange="update_boundaryContact(this.value)">
    <option value="all four steps">all four steps</option>
    <option value="thermal contact (isothermal steps)">thermal contact (isothermal)</option>
    <option value="insulated (adiabatic steps)">insulated (adiabatic)</option>
  </select>
</label>
<label>View:
  <select id="representationInput" onchange="update_representation(this.value)">
    <option value="piston panels">piston panels</option>
    <option value="p-V path">p–V path</option>
    <option value="side by side">side by side</option>
  </select>
</label>
<span style="font-size:10.5px;color:#666;line-height:1.45">Hover a cylinder or a curve leg for a label; click for the full explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var cDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

var C = {
  hotFill: '#f0adae', hotStroke: '#dd8e8f',
  insFill: '#fbe1d5', insStroke: '#9d928b',
  coldFill: '#a9cadd', coldStroke: '#7f9aab',
  cyl: '#8f8f8f',
  gas: '#e3e3e3', dot: '#8a8a8a',
  piston: '#dcdcf2', pistonS: '#9b9bc4',
  work: '#5aa84f', heat: '#8b8b8b',
  text: '#1a1a1a',
  hotCurve: '#cc4f4f', coldCurve: '#3a7fb0', adiabat: '#555555',
  ring: '#f0a02a'
};
var MATHFAM = '"Times New Roman", Times, serif';
var UIFAM = 'Helvetica, Arial, sans-serif';

var state = { cycleStep: 'fullCycle', boundary: 'all four steps', rep: 'piston panels' };

/* ---------- small helpers ---------- */
function makeRnd(seed) { var s = seed || 1; return function () { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; }; }

function richText(parent, x, y, parts, opt) {
  opt = opt || {};
  var size = opt.size || 14;
  var t = parent.text(function (add) {
    var cur = 0;
    parts.forEach(function (p) {
      var target = p.sub ? size * 0.30 : 0;
      var sp = add.tspan(p.t);
      sp.font({
        style: p.italic ? 'italic' : 'normal',
        weight: p.bold ? 'bold' : 'normal',
        size: p.sub ? size * 0.72 : size
      });
      if (Math.abs(target - cur) > 0.001) { sp.attr('dy', target - cur); cur = target; }
    });
  });
  t.font({ family: opt.family || UIFAM, size: size, anchor: opt.anchor || 'middle', fill: opt.fill || C.text });
  t.attr({ x: x, y: y });
  if (opt.halo) t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
  return t;
}

function vArrow(g, x, yFrom, yTo, color, w, hw, hl) {
  var dir = (yTo > yFrom) ? 1 : -1;
  var baseY = yTo - dir * hl;
  g.line(x, yFrom, x, baseY).stroke({ color: color, width: w, linecap: 'butt' });
  g.polygon([[x - hw, baseY], [x + hw, baseY], [x, yTo]]).fill(color);
}

function stipple(g, x, y, w, h, seed) {
  var rnd = makeRnd(seed);
  var cols = Math.max(2, Math.round(w / 15)), rows = Math.max(2, Math.round(h / 15));
  for (var r = 0; r < rows; r++) for (var c = 0; c < cols; c++) {
    var px = x + (c + 0.5) * (w / cols) + (rnd() - 0.5) * (w / cols) * 0.7;
    var py = y + (r + 0.5) * (h / rows) + (rnd() - 0.5) * (h / rows) * 0.7;
    g.circle(4).center(px, py).fill(C.dot).opacity(0.82);
  }
}

/* ---------- panel data ---------- */
var CP = { BW: 150, BH: 340, BY: 8, BX0: 10, GAP: 12, cylHalf: 30, cylBottom: 250 };

var PANELS = [
  {
    fill: C.hotFill, stroke: C.hotStroke, block: 'Reservoir', temp: 'h', gasH: 80, up: true, heat: 'in',
    w: '1', caps: ['Step 1:', 'Isothermal', 'expansion', '(M\u2192N)'],
    tip: 'Step 1 \u2014 isothermal expansion at T_h: heat Q_h in, work W\u2081 out',
    ptitle: 'Step 1 \u2014 Isothermal expansion (M\u2192N)',
    pbody: 'The gas sits on the hot reservoir at T_h. As it expands it lifts the piston and does work W\u2081, while heat Q_h flows in at exactly the rate needed to hold the temperature fixed. With \u0394U = 0 for an isothermal ideal gas, Q_h = W\u2081.'
  },
  {
    fill: C.insFill, stroke: C.insStroke, block: 'Insulation', temp: null, gasH: 150, up: true, heat: null,
    w: '2', caps: ['Step 2:', 'Adiabatic', 'expansion', '(N\u2192O)'],
    tip: 'Step 2 \u2014 adiabatic expansion: Q = 0, gas cools from T_h to T_c',
    ptitle: 'Step 2 \u2014 Adiabatic expansion (N\u2192O)',
    pbody: 'Now the cylinder is wrapped in insulation, so no heat arrow appears: Q = 0. The expanding gas still does work W\u2082, but that energy can only come out of its own internal energy, so the gas cools from T_h down to T_c.'
  },
  {
    fill: C.coldFill, stroke: C.coldStroke, block: 'Reservoir', temp: 'c', gasH: 155, up: false, heat: 'out',
    w: '3', caps: ['Step 3:', 'Isothermal', 'compression', '(O\u2192P)'],
    tip: 'Step 3 \u2014 isothermal compression at T_c: work W\u2083 in, heat Q_c out',
    ptitle: 'Step 3 \u2014 Isothermal compression (O\u2192P)',
    pbody: 'On the cold reservoir at T_c the piston is pushed down, doing work W\u2083 on the gas. An equal amount of heat Q_c is dumped into the cold reservoir, so the temperature never rises. This is the only place heat leaves the working substance.'
  },
  {
    fill: C.insFill, stroke: C.insStroke, block: 'Insulation', temp: null, gasH: 70, up: false, heat: null,
    w: '4', caps: ['Step 4:', 'Adiabatic', 'compression', '(P\u2192M)'],
    tip: 'Step 4 \u2014 adiabatic compression: Q = 0, gas warms from T_c back to T_h',
    ptitle: 'Step 4 \u2014 Adiabatic compression (P\u2192M)',
    pbody: 'Insulated again, the work W\u2084 done on the gas has nowhere to go but internal energy, so the temperature climbs from T_c back to T_h at the smallest volume. The gas is returned to state M and the cycle can repeat exactly.'
  }
];
var STEPIDS = ['step1_MN', 'step2_NO', 'step3_OP', 'step4_PM'];

function stepIdx() {
  var i = STEPIDS.indexOf(state.cycleStep);
  return i;
}
function boundaryOK(i) {
  var b = state.boundary;
  if (b.indexOf('thermal') === 0) return (i === 0 || i === 2);
  if (b.indexOf('insulated') === 0) return (i === 1 || i === 3);
  return true;
}
function legActive(i) {
  var s = stepIdx();
  return ((s < 0) || (s === i)) && boundaryOK(i);
}
function anySelection() { return stepIdx() >= 0 || state.boundary !== 'all four steps'; }

/* ---------- piston panels ---------- */
function drawPanel(root, i, bx, forceActive) {
  var P = PANELS[i];
  var cx = bx + CP.BW / 2;
  var cl = cx - CP.cylHalf, cr = cx + CP.cylHalf;
  var g = root.group();
  var active = forceActive ? true : legActive(i);
  var dim = !active;

  // surround block (only the coloured fill dims)
  g.rect(CP.BW, CP.BH).move(bx, CP.BY)
    .fill({ color: P.fill, opacity: dim ? 0.40 : 1 })
    .stroke({ color: P.stroke, width: 1.8, opacity: dim ? 0.55 : 1 });

  var art = g.group();
  // cylinder interior (white channel) + walls
  art.rect(CP.cylHalf * 2, CP.cylBottom - CP.BY).move(cl, CP.BY).fill('#ffffff');
  art.path('M' + cl + ',' + CP.BY + ' L' + cl + ',' + CP.cylBottom + ' L' + cr + ',' + CP.cylBottom + ' L' + cr + ',' + CP.BY)
    .fill('none').stroke({ color: C.cyl, width: 3.2, linejoin: 'round' });

  // gas + stipple
  var gasTop = CP.cylBottom - P.gasH;
  art.rect(CP.cylHalf * 2 - 4, P.gasH).move(cl + 2, gasTop).fill(C.gas);
  stipple(art, cl + 4, gasTop + 4, CP.cylHalf * 2 - 12, P.gasH - 8, 17 + i * 91);

  // piston slab + stem
  var pistonH = 11, stemW = 12, stemH = 34;
  art.rect(CP.cylHalf * 2 - 4, pistonH).move(cl + 2, gasTop - pistonH).fill(C.piston).stroke({ color: C.pistonS, width: 1 });
  art.rect(stemW, stemH).move(cx - stemW / 2, gasTop - pistonH - stemH).fill(C.piston).stroke({ color: C.pistonS, width: 1 });

  // work arrow
  var ax = cx - 23, L = 48, labelY;
  if (P.up) {
    var tail = gasTop - pistonH - 6, head = tail - L;
    vArrow(art, ax, tail, head, C.work, 2.3, 5, 10);
    labelY = head - 8;
  } else {
    var head2 = gasTop - pistonH - 6, tail2 = head2 - L;
    vArrow(art, ax, tail2, head2, C.work, 2.3, 5, 10);
    labelY = tail2 - 8;
  }

  // heat arrow (reservoir panels only; boundary filter can hide it)
  var showHeat = P.heat && boundaryOK(i);
  if (showHeat) {
    if (P.heat === 'in') vArrow(art, cx, 296, 256, C.heat, 9, 10, 15);
    else vArrow(art, cx, 256, 296, C.heat, 9, 10, 15);
  }
  art.opacity(dim ? 0.75 : 1);

  // ---- text layer: always full opacity ----
  var txt = g.group();
  richText(txt, ax, labelY, [{ t: 'W', italic: true }, { t: P.w, sub: true }],
    { size: 18, family: MATHFAM, halo: true });
  if (showHeat) {
    richText(txt, cx, 314, [{ t: 'Q', italic: true }, { t: (P.heat === 'in' ? 'h' : 'c'), sub: true }],
      { size: 18, family: MATHFAM, halo: true });
  }
  richText(txt, cx, 340, [{ t: P.block }], { size: 15.5, halo: true });
  if (P.temp) {
    richText(txt, cx, 370, [{ t: '(Temperature ' }, { t: 'T', italic: true }, { t: P.temp, sub: true }, { t: ')' }],
      { size: 14, family: MATHFAM });
  }
  var capY = 400;
  for (var k = 0; k < P.caps.length; k++) {
    richText(txt, cx, capY + k * 19, [{ t: P.caps[k], bold: (k === 0) }], { size: k === 0 ? 15.5 : 14.5 });
  }

  if (active && anySelection()) {
    g.rect(CP.BW + 10, CP.BH + 10).move(bx - 5, CP.BY - 5).radius(5)
      .fill('none').stroke({ color: C.ring, width: 2.8 });
  }

  // hit area for hover / click
  var hit = g.rect(CP.BW + 10, 470).move(bx - 5, 2).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(P.tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      state.cycleStep = STEPIDS[i];
      syncControls(); render();
      showPopup(P.ptitle, P.pbody);
    });
  return g;
}

function drawPanels(root) {
  for (var i = 0; i < 4; i++) drawPanel(root, i, CP.BX0 + i * (CP.BW + CP.GAP));
  return root;
}

/* ---------- p-V diagram ---------- */
var GAM = 1.9, TH = 1.0, TC = 0.45, VM = 1.0, VN = 1.7;
var RAT = Math.pow(TH / TC, 1 / (GAM - 1));
var VO = VN * RAT, VP = VM * RAT;
var pM = TH / VM, pN = TH / VN, pO = TC / VO, pP = TC / VP;

var fIsoH = compileExpr(TH + '/V', ['V']);
var fIsoC = compileExpr(TC + '/V', ['V']);
var fAdNO = compileExpr(pN.toFixed(6) + '*(' + VN.toFixed(6) + '/V)^' + GAM, ['V']);
var fAdPM = compileExpr(pP.toFixed(6) + '*(' + VP.toFixed(6) + '/V)^' + GAM, ['V']);

function pvx(V) { return 82 + (V - 0.7) * (500 / 4.2); }
function pvy(p) { return 372 - (p - 0.05) * (312 / 1.10); }

function sampleCurve(fn, a, b, n) {
  var pts = [];
  for (var k = 0; k < n; k++) {
    var V = a + (b - a) * (k / (n - 1));
    pts.push([pvx(V), pvy(fn(V))]);
  }
  return pts;
}
function ptsAttr(p) { return p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' '); }

function midArrow(g, pts, color, size) {
  var k = Math.floor(pts.length / 2);
  var a = pts[k - 1], b = pts[k + 1];
  var dx = b[0] - a[0], dy = b[1] - a[1], L = Math.sqrt(dx * dx + dy * dy) || 1;
  dx /= L; dy /= L;
  var nx = -dy, ny = dx, c = pts[k];
  var tip = [c[0] + dx * size, c[1] + dy * size];
  var bx = c[0] - dx * size * 0.5, by = c[1] - dy * size * 0.5;
  return g.polygon([[bx + nx * size * 0.62, by + ny * size * 0.62], [bx - nx * size * 0.62, by - ny * size * 0.62], tip]).fill(color);
}

function drawPV(root, opts) {
  opts = opts || {};
  var g = root.group();

  var SEGS = [
    { fn: fIsoH, a: VM, b: VN, color: C.hotCurve, tip: 'M\u2192N: isothermal expansion at T_h (heat Q_h in)', idx: 0 },
    { fn: fAdNO, a: VN, b: VO, color: C.adiabat, tip: 'N\u2192O: adiabatic expansion, Q = 0 (T_h \u2192 T_c)', idx: 1 },
    { fn: fIsoC, a: VO, b: VP, color: C.coldCurve, tip: 'O\u2192P: isothermal compression at T_c (heat Q_c out)', idx: 2 },
    { fn: fAdPM, a: VP, b: VM, color: C.adiabat, tip: 'P\u2192M: adiabatic compression, Q = 0 (T_c \u2192 T_h)', idx: 3 }
  ];
  var sampled = SEGS.map(function (s) { return sampleCurve(s.fn, s.a, s.b, 60); });

  // shaded loop interior
  var loop = [];
  sampled.forEach(function (p) { loop = loop.concat(p); });
  g.polygon(ptsAttr(loop)).fill('#bcd9f2').opacity(0.42).stroke('none');

  // dashed isotherm guides
  g.polyline(ptsAttr(sampleCurve(fIsoH, 0.85, 4.85, 80))).fill('none')
    .stroke({ color: C.hotCurve, width: 1.2, dasharray: '5,4' }).opacity(0.7);
  g.polyline(ptsAttr(sampleCurve(fIsoC, 0.85, 4.85, 80))).fill('none')
    .stroke({ color: C.coldCurve, width: 1.2, dasharray: '5,4' }).opacity(0.7);

  // axes
  g.line(66, 372, 592, 372).stroke({ color: '#333', width: 1.7 });
  g.polygon([[592, 367], [592, 377], [602, 372]]).fill('#333');
  g.line(66, 372, 66, 44).stroke({ color: '#333', width: 1.7 });
  g.polygon([[61, 44], [71, 44], [66, 34]]).fill('#333');
  richText(g, 600, 393, [{ t: 'V', italic: true }], { size: 18, family: MATHFAM });
  richText(g, 48, 44, [{ t: 'p', italic: true }], { size: 18, family: MATHFAM });

  // curve legs
  SEGS.forEach(function (s, k) {
    var on = legActive(s.idx);
    var pts = sampled[k];
    var w = on ? (anySelection() ? 4.4 : 3.2) : 2;
    g.polyline(ptsAttr(pts)).fill('none')
      .stroke({ color: s.color, width: w, linecap: 'round', linejoin: 'round' })
      .opacity(on ? 1 : 0.32);
    midArrow(g, pts, s.color, on ? 9 : 7).opacity(on ? 1 : 0.32);
    var hit = g.polyline(ptsAttr(pts)).fill('none').stroke({ color: '#fff', width: 15, linecap: 'round' }).opacity(0);
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip(s.tip, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        state.cycleStep = STEPIDS[s.idx];
        syncControls(); render();
        showPopup(PANELS[s.idx].ptitle, PANELS[s.idx].pbody);
      });
  });

  // corner points + labels
  var corners = [
    { V: VM, p: pM, t: 'M', x: -11, y: -7, an: 'end' },
    { V: VN, p: pN, t: 'N', x: 10, y: -8, an: 'start' },
    { V: VO, p: pO, t: 'O', x: 9, y: -12, an: 'start' },
    { V: VP, p: pP, t: 'P', x: -9, y: 17, an: 'end' }
  ];
  corners.forEach(function (c) {
    var X = pvx(c.V), Y = pvy(c.p);
    g.circle(7).center(X, Y).fill('#2b2b2b');
    richText(g, X + c.x, Y + c.y, [{ t: c.t, italic: true }], { size: 17, family: MATHFAM, anchor: c.an, halo: true });
  });

  // isotherm guide labels
  richText(g, 585, pvy(TH / 4.85) - 6, [{ t: 'T', italic: true }, { t: 'h', sub: true }],
    { size: 16, family: MATHFAM, anchor: 'start', fill: C.hotCurve, halo: true });
  richText(g, 585, pvy(TC / 4.85) + 16, [{ t: 'T', italic: true }, { t: 'c', sub: true }],
    { size: 16, family: MATHFAM, anchor: 'start', fill: C.coldCurve, halo: true });

  // net work callout with leader
  g.line(408, 196, 266, 292).stroke({ color: '#7a7a7a', width: 1, dasharray: '3,3' });
  g.circle(5).center(266, 292).fill('#7a7a7a');
  richText(g, 415, 190, [{ t: 'net work ' }, { t: 'W', italic: true }], { size: 15, anchor: 'start', halo: true });

  // legend
  if (opts.legend !== false) {
    var lg = g.group(), ly = 432;
    function swatch(x, fill, stroke) { lg.rect(17, 12).move(x, ly - 10).fill(fill).stroke({ color: stroke, width: 1 }); }
    lg.line(16, ly - 4, 33, ly - 4).stroke({ color: C.work, width: 2.6 });
    lg.polygon([[33, ly - 8], [33, ly], [41, ly - 4]]).fill(C.work);
    richText(lg, 46, ly, [{ t: 'work' }], { size: 13, anchor: 'start' });
    lg.line(96, ly - 4, 112, ly - 4).stroke({ color: C.heat, width: 7 });
    lg.polygon([[112, ly - 9], [112, ly + 1], [121, ly - 4]]).fill(C.heat);
    richText(lg, 127, ly, [{ t: 'heat' }], { size: 13, anchor: 'start' });
    swatch(172, C.hotFill, C.hotStroke); richText(lg, 194, ly, [{ t: 'hot reservoir' }], { size: 13, anchor: 'start' });
    swatch(288, C.coldFill, C.coldStroke); richText(lg, 310, ly, [{ t: 'cold reservoir' }], { size: 13, anchor: 'start' });
    swatch(408, C.insFill, C.insStroke); richText(lg, 430, ly, [{ t: 'insulation' }], { size: 13, anchor: 'start' });
    lg.line(506, ly - 4, 528, ly - 4).stroke({ color: '#888', width: 1.2, dasharray: '5,4' });
    richText(lg, 534, ly, [{ t: 'isotherms' }], { size: 13, anchor: 'start' });
  }
  return g;
}

/* ---------- render ---------- */
function render() {
  cDraw.clear();
  if (state.rep === 'piston panels') {
    cDraw.viewbox(0, 0, 656, 478);
    drawPanels(cDraw.group());
  } else if (state.rep === 'p-V path') {
    cDraw.viewbox(0, 0, 640, 470);
    var gp = cDraw.group(); drawPV(gp); gp.attr('transform', 'translate(8,8)');
  } else {
    // side by side: the selected cylinder next to the matching p-V leg
    cDraw.viewbox(0, 0, 762, 478);
    var s = stepIdx();
    var pick = (s >= 0 && boundaryOK(s)) ? s : [0, 1, 2, 3].filter(boundaryOK)[0];
    var a = cDraw.group(); drawPanel(a, pick, 8, true);
    var b = cDraw.group(); drawPV(b, { legend: false });
    b.attr('transform', 'translate(186,14) scale(0.90)');
  }
}

/* ---------- controls ---------- */
function syncControls() {
  document.getElementById('cycleStepInput').value = state.cycleStep;
  document.getElementById('boundaryContactInput').value = state.boundary;
  document.getElementById('representationInput').value = state.rep;
}
function update_cycleStep(v) { state.cycleStep = v; render(); }
function update_boundaryContact(v) { state.boundary = v; render(); }
function update_representation(v) { state.rep = v; render(); }

function showKeyInsight() {
  showPopup('Why only T_h and T_c matter',
    'Heat enters the working gas only during the hot isothermal leg and leaves only during the cold isothermal leg; the two insulated legs carry the gas between T_h and T_c with Q = 0. Because the closed loop returns to its starting state, the enclosed area is the net work W = Q_h \u2212 Q_c, and for reversible isotherms Q_c/Q_h = T_c/T_h, so the efficiency is 1 \u2212 T_c/T_h.');
}

/* ---------- demo player ---------- */
var demoSteps = [
  {
    title: 'The Carnot cycle \u2014 four reversible steps',
    narration: 'All four steps are shown together: two isothermal steps in contact with a reservoir (red hot, blue cold) and two adiabatic steps under insulation. Green arrows are work, thick gray arrows are heat. Press \u25b6 to walk through the cycle.',
    state: { cycleStep: 'fullCycle', boundary: 'all four steps', rep: 'piston panels' }
  },
  { title: 'Step 1 \u2014 Isothermal expansion (M\u2192N)', narration: 'The cylinder sits on the hot reservoir at T_h. Heat Q_h flows in (gray arrow up) exactly as fast as the gas does work W\u2081 lifting the piston, so the temperature never changes and the gas expands.', state: { cycleStep: 'step1_MN', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 2 \u2014 Adiabatic expansion (N\u2192O)', narration: 'The cylinder is now wrapped in insulation, so no heat arrow appears. The gas keeps expanding and does work W\u2082, but that energy can only come from its own internal energy, so it cools from T_h to T_c.', state: { cycleStep: 'step2_NO', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 3 \u2014 Isothermal compression (O\u2192P)', narration: 'Placed on the cold reservoir at T_c, the gas is compressed: work W\u2083 is done on it downward while heat Q_c is dumped out to the cold reservoir, holding the temperature fixed.', state: { cycleStep: 'step3_OP', boundary: 'all four steps', rep: 'piston panels' } },
  { title: 'Step 4 \u2014 Adiabatic compression (P\u2192M)', narration: 'Insulated again, the gas is compressed to its smallest volume by work W\u2084 with no heat exchange, which raises its temperature back to T_h and returns it to state M.', state: { cycleStep: 'step4_PM', boundary: 'all four steps', rep: 'piston panels' } },
